            Node("cycleWord_critical_blocks", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. Elaborated telescope and kernel/native/project acceptance are unavailable.", "theorem cycleWord_critical_blocks (m : Nat) (hm : 3 ≤ m) :\n    criticalFaces (cycleWord m hm) =\n      (pathCritical (cyclePathTail m hm)).image (insert (secondLabel m hm)) ∪\n      (pathCritical (cyclePathLast m hm)).image (insert (lastLabel m))", DescribeRole.Theorem),
            Node("pathChosen_labelInterval", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. Elaborated telescope and kernel/native/project acceptance are unavailable.", "theorem pathChosen_labelInterval (m lo n : Nat) (h : lo + n ≤ m + 1) (x : Label m) :\n    x ∈ FiniteIndependentPathGreedy.pathChosen (labelInterval m lo n h) ↔\n      lo + 1 ≤ x.val ∧ x.val < lo + n ∧ x.val % 3 = (lo + 1) % 3", DescribeRole.Theorem),
            Node("tailWord_critical_formula", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. Elaborated telescope and kernel/native/project acceptance are unavailable.", "theorem tailWord_critical_formula (m : Nat) (hm : 3 ≤ m) :\n    criticalFaces (tailWord m hm) =\n      if m % 3 = 2 then ∅ else {tailCritical m hm}", DescribeRole.Theorem),
            Node("cycleWord_critical_formula", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. Elaborated telescope and kernel/native/project acceptance are unavailable.", "theorem cycleWord_critical_formula (m : Nat) (hm : 3 ≤ m) :\n    criticalFaces (cycleWord m hm) =\n      if m % 3 = 0 then {labelsCongruent m 2 2, labelsCongruent m 0 3}\n      else if m % 3 = 1 then {labelsCongruent m 2 2}\n      else {insert (lastLabel m) (labelsCongruent m 0 3)}", DescribeRole.Theorem),
